// passwordstore — encrypted password manager
// KDF: 100000, key size: 32

fn pws_derive::(master_password, salt_b64) {
    return @crypto_pbkdf2(master_password, @base64_decode(salt_b64), 16, 32);
}

fn pws_open::(dir, master_password) {
    let salt_path = @path_join(dir, ".salt");
    let salt_b64 = null;
    if (@exists(salt_path)) { salt_b64 = @read_text(salt_path); }
    else {
        salt_b64 = @base64(@crypto_random_bytes(32));
        @mkdir(dir);
        @write_text(salt_path, salt_b64);
    }
    return {"dir": dir, "salt": salt_b64, "key": pws_derive(master_password, salt_b64)};
}

fn pws_entry_path::(store, name) {
    return @path_join(store["dir"], @str_slugify(name) + ".enc");
}

fn pws_store::(store, name, password) {
    let mem = @mem_from_bytes(@bytes(password));
    @mem_encrypt(mem, store["key"]);
    let cipher = @base64(@mem_to_bytes(mem));
    @free(mem);
    @write_text(pws_entry_path(store, name), cipher);
    return true;
}

fn pws_load::(store, name) {
    let path = pws_entry_path(store, name);
    if (!@exists(path)) { return null; }
    let cipher = @base64_decode(@read_text(path));
    let mem = @mem_from_bytes(cipher);
    @mem_decrypt(mem, store["key"]);
    let password = @mem_to_string(mem);
    @mem_secure_wipe(mem);
    @free(mem);
    return password;
}

fn pws_delete::(store, name) {
    let path = pws_entry_path(store, name);
    if (!@exists(path)) { return false; }
    @remove(path);
    return true;
}

fn pws_list::(store) {
    let files = @listdir(store["dir"]);
    let out = [];
    for f in files {
        let base = @basename(f);
        if (@ends_with(base, ".enc")) { @push(out, @str_remove_suffix(base, ".enc")); }
    }
    @sort(out);
    return out;
}

fn pws_generate::(store, name, length) {
    let alphabet = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*";
    let pw = "";
    for i in @range(0, length) {
        let idx = @crypto_random_int(0, @len(alphabet) - 1);
        pw += @str_char_at(alphabet, idx);
    }
    pws_store(store, name, pw);
    return pw;
}

fn version::() { return "1.0.0"; }
